import{c as h}from"./chunk-EJZJNXKG.js";h();var e=(t,n,o,r)=>[{text:t,response:r,grace:30},{text:n,response:"Pause and consider who your choice serves. This retelling lets you reflect; read the passage to see how the biblical account unfolds.",grace:10},{text:o,response:"Fear and self-interest can narrow our choices. Consider the passage and the people affected before you continue.",grace:10}],d=[{id:"david",title:"David \xB7 A Courageous Heart",subtitle:"From the sheepfold to the valley",colour:"#88a760",virtue:"Courage & mercy",chapters:[{title:"Faithful in small things",reference:"1 Samuel 16:1\u201313; 17:34\u201337",place:"Bethlehem pastures",opening:"Your brothers are away. The flock still needs care. Before anyone notices David, his ordinary responsibilities matter.",objective:"Walk the pasture and gather the shepherd\u2019s preparations.",discoveries:["A lost lamb\u2019s trail","The shepherd\u2019s staff","Water for the flock"],question:"A lamb wanders while you hope for a greater calling. What do you do?",choices:e("Care for the lamb and finish the work entrusted to me.","Leave the flock to make sure I am noticed.","Tell someone else it is their problem.","Faithfulness begins with caring for what has already been entrusted to you."),ending:"The flock is safe. The road to the valley begins with faithful care."},{title:"Bread for your brothers",reference:"1 Samuel 17:12\u201322",place:"The camp road",opening:"Jesse sends food to the army and asks for news. You arrive carrying provisions, not a royal title.",objective:"Find the supplies and the message for the camp.",discoveries:["Bread for the soldiers","Cheese for the captain","Jesse\u2019s message"],question:"The camp is noisy and frightened. What comes first?",choices:e("Deliver the provisions and ask after my brothers.","Abandon the food and chase the loudest argument.","Pretend I have already been made a commander.","Service and attention to others are part of courage."),ending:"Your brothers receive their provisions. Across the valley, a challenge rings out."},{title:"A valley of fear",reference:"1 Samuel 17:23\u201337",place:"Valley of Elah",opening:"Goliath\u2019s challenge has silenced the camp. Eliab questions your motives. Saul doubts your age and experience.",objective:"Listen to the camp\u2019s voices before answering Saul.",discoveries:["A soldier\u2019s concern","Eliab\u2019s warning","Saul\u2019s summons"],question:"How will you respond to mockery and fear?",choices:e("Speak calmly about God\u2019s faithfulness without belittling the soldiers.","Insult everyone who feels afraid.","Promise victory because I want everyone to admire me.","Biblical courage need not humiliate frightened people."),ending:"You speak before Saul. Confidence is tested by what it rests upon."},{title:"Five smooth stones",reference:"1 Samuel 17:38\u201340",place:"The brook",opening:"Saul offers armour. It is unfamiliar and heavy. You step toward the brook with a sling and the skills you have practised.",objective:"Explore the brook and prepare for the encounter.",discoveries:["Smooth stones","The sling","The shepherd\u2019s bag"],question:"The armour does not fit. What do you choose?",choices:e("Be honest about my limits and use what I know.","Wear the armour only to look impressive.","Blame Saul for not solving everything for me.","Humility includes recognising both your limits and the gifts you can use."),ending:"The armour stays behind. The scene opens across the valley."},{title:"Across the valley",reference:"1 Samuel 17:41\u201350",place:"The encounter",opening:"Goliath advances. The armies watch. The biblical account places David\u2019s confidence in the Lord, rather than his appearance.",objective:"Reach the valley markers and steady your purpose.",discoveries:["The valley crossing","A steady footing","The camp behind you"],question:"What gives this encounter its meaning?",choices:e("Trust God and act to protect the threatened people.","Use the moment to promise I will never need anyone.","Make revenge and personal glory my purpose.","The account points beyond David\u2019s strength to the God he trusts."),ending:"In this non-graphic retelling, the giant falls and the frightened camp finds hope."},{title:"The strength to show mercy",reference:"1 Samuel 24:1\u201322",place:"The wilderness cave",opening:"Years later, Saul is vulnerable before you. Your companions call it a chance to take revenge.",objective:"Find the witnesses and consider the cost of revenge.",discoveries:["A companion\u2019s counsel","A piece of the royal robe","The cave entrance"],question:"With power over an enemy, what will you do?",choices:e("Refuse revenge and speak truth while keeping a safe distance.","Treat another person\u2019s vulnerability as permission to harm them.","Let my companions decide my conscience for me.","Mercy can require more strength than retaliation. David\u2019s story invites courage with restraint."),ending:"You leave the cave without taking Saul\u2019s life. Courage has become mercy. Campaign complete."}]},{id:"ruth",title:"Ruth \xB7 Fields of Faithfulness",subtitle:"A journey of loyalty, work, and belonging",colour:"#d2b06b",virtue:"Loyalty & kindness",chapters:[{title:"At the crossroads",reference:"Ruth 1:1\u201318",place:"The road from Moab",opening:"Naomi is returning to Bethlehem after deep loss. She releases you from any obligation to follow her.",objective:"Gather what the journey will require.",discoveries:["A travelling cloak","Water for Naomi","The road to Bethlehem"],question:"How will you answer Naomi?",choices:e("Freely choose to walk beside her, listening to her grief.","Demand that she be cheerful before I help.","Promise support only if there is a reward.","Ruth\u2019s freely chosen loyalty makes room for grief, uncertainty, and faithful companionship."),ending:"Together you turn toward Bethlehem. The long walk begins."},{title:"Arriving with little",reference:"Ruth 1:19\u201322; 2:1\u20133",place:"Bethlehem",opening:"People recognise Naomi. You are a newcomer, and the barley harvest has begun.",objective:"Discover the village and a place to work safely.",discoveries:["The village welcome","Harvest customs","The field boundary"],question:"How will you seek provision?",choices:e("Ask to glean and work respectfully within the harvest customs.","Take whatever I want without speaking to anyone.","Refuse help because needing others feels embarrassing.","Receiving help and contributing through honest work can belong together."),ending:"The morning light spreads across the barley. You enter the field."},{title:"Behind the reapers",reference:"Ruth 2:4\u201313",place:"Boaz\u2019s field",opening:"Boaz asks about you. He offers safety, water, and a place among the women harvesting.",objective:"Visit the harvest stations and gather the day\u2019s gleanings.",discoveries:["Fallen barley","The water jar","The reapers\u2019 shelter"],question:"How do you receive unexpected kindness?",choices:e("Receive it with gratitude and respect the other workers.","Assume kindness means everyone now owes me more.","Hide the water so nobody else can use it.","Kindness creates room for dignity and shared provision."),ending:"The field becomes more than a workplace: there is room for you here."},{title:"Enough to share",reference:"Ruth 2:14\u201323",place:"The evening return",opening:"At the meal, there is more than you can eat. Naomi waits at home, and you carry the harvest back.",objective:"Prepare the harvest and evening meal.",discoveries:["Roasted grain","A generous measure","Naomi\u2019s doorway"],question:"What will you do with the extra provision?",choices:e("Bring food home and tell Naomi how the day went.","Keep the whole harvest secret.","Measure Naomi\u2019s worth by how much she can earn.","Provision becomes an opportunity to care for someone else."),ending:"Naomi sees the grain and hears the name Boaz. Hope returns in small, concrete ways."},{title:"An honest request",reference:"Ruth 3:1\u201318",place:"The threshing floor",opening:"Naomi suggests a way to ask for family protection. Ruth makes a direct request. Boaz explains that another relative has the first claim.",objective:"Find the signs of family responsibility and patient trust.",discoveries:["Naomi\u2019s counsel","The threshing floor","The morning grain"],question:"There is another person\u2019s rightful part in the decision. How do you proceed?",choices:e("Ask honestly and allow the matter to be settled properly.","Pressure Boaz to ignore the other relative.","Spread a false story to force an answer.","Faithful choices include honesty, patience, and respect for others\u2019 responsibilities."),ending:"You return to Naomi. Some things now require patient waiting."},{title:"A place in the story",reference:"Ruth 4:1\u201322",place:"The town gate",opening:"The family matter is settled publicly. Ruth and Naomi\u2019s story moves from loss toward belonging and new life.",objective:"Visit the witnesses to the village\u2019s new beginning.",discoveries:["The town witnesses","The family blessing","Naomi\u2019s renewed hope"],question:"What will you carry forward from this journey?",choices:e("Make room for outsiders and practise loyal kindness.","Decide that belonging should be kept from newcomers.","Forget everyone who helped when I had little.","Ruth\u2019s story honours loyalty, generosity, and the outsider welcomed into a family."),ending:"The women bless Naomi. A new generation begins, and Ruth\u2019s place in the story is remembered. Campaign complete."}]},{id:"esther",title:"Esther \xB7 For Such a Time",subtitle:"Wisdom and courage in the Persian court",colour:"#b397d0",virtue:"Courage & advocacy",chapters:[{title:"Behind palace doors",reference:"Esther 2:5\u201320",place:"The Persian court",opening:"Esther lives within a powerful court where many choices are not hers to control. Mordecai continues to care about her welfare.",objective:"Learn the court\u2019s layout and listen to trusted counsel.",discoveries:["The palace gate","A trusted attendant","Mordecai\u2019s message"],question:"In an unfamiliar place, how will you seek wisdom?",choices:e("Listen carefully and protect the dignity of those around me.","Assume status makes me wiser than everyone else.","Dismiss anyone who lacks influence.","Wisdom often begins with listening rather than performing confidence."),ending:"You learn the rhythms of the court. A quiet responsibility grows."},{title:"News at the gate",reference:"Esther 3:1\u201315; 4:1\u20138",place:"The gate messenger",opening:"A decree threatens the Jewish people. Mordecai sends evidence through a messenger, asking Esther to speak.",objective:"Gather the facts before deciding how to respond.",discoveries:["A copy of the decree","The messenger\u2019s account","The people in mourning"],question:"The danger reaches beyond the palace. What comes first?",choices:e("Listen to the threatened community and understand the facts.","Ignore the decree because my room feels safe.","Spread an unverified rumour to gain attention.","Responsible advocacy begins with hearing people and understanding what threatens them."),ending:"The message reaches you. Silence now has consequences."},{title:"The cost of speaking",reference:"Esther 4:9\u201317",place:"Esther\u2019s chambers",opening:"Approaching the king without being summoned carries real danger. Mordecai asks whether this is the moment for which Esther has come to royal position.",objective:"Seek support before taking a difficult step.",discoveries:["Mordecai\u2019s reply","The community\u2019s fast","A request for support"],question:"How will you meet the risk?",choices:e("Ask the community to stand with me and prepare to speak.","Pretend there is no danger and mock those who are afraid.","Trade the community\u2019s safety for my own comfort.","Courage can acknowledge danger and seek the support of others."),ending:"You do not face the moment alone. The doors of the inner court stand ahead."},{title:"The inner court",reference:"Esther 5:1\u20138",place:"Before the throne",opening:"Esther enters the court. The king extends the golden sceptre. She invites the king and Haman to a banquet.",objective:"Cross the court and prepare a thoughtful appeal.",discoveries:["The court entrance","The extended sceptre","The banquet invitation"],question:"You have an opportunity to speak. How will you use it?",choices:e("Choose a thoughtful time and make a clear, respectful appeal.","Turn the moment into a speech about my importance.","Humiliate the attendants to show authority.","Wisdom joins courage to timing, clarity, and respect."),ending:"The invitation is accepted. The story\u2019s tension moves to the banquet."},{title:"Name the truth",reference:"Esther 7:1\u20136",place:"The banquet",opening:"At the banquet, the king again asks what Esther requests. She identifies herself with the people under threat.",objective:"Gather the evidence and the words of the appeal.",discoveries:["The people\u2019s petition","The decree\u2019s consequences","A truthful appeal"],question:"What will be the centre of your request?",choices:e("Ask for my people\u2019s lives and name the threat truthfully.","Ask only for more luxury for myself.","Invent evidence because the cause feels urgent.","Integrity matters especially when speaking against injustice."),ending:"The hidden threat is brought into the open. The appeal has been heard."},{title:"Remember and protect",reference:"Esther 8:1\u201317; 9:20\u201322",place:"The public square",opening:"The story turns toward protection and remembrance. Purim is established as a time of joy, sharing food, and gifts to the poor.",objective:"Prepare the signs of remembrance and care.",discoveries:["Letters of protection","Gifts of food","Provision for the poor"],question:"How should a community remember deliverance?",choices:e("Remember truthfully and share practical care with those in need.","Use the celebration to ignore people who are hungry.","Make remembrance only about praising myself.","Esther\u2019s story ends with remembrance that includes generosity."),ending:"The letters go out, and gifts are shared. Courage has become care for a community. Campaign complete."}]},{id:"daniel",title:"Daniel \xB7 An Undivided Heart",subtitle:"Integrity from the court to the lions\u2019 den",colour:"#88b4bd",virtue:"Integrity & prayer",chapters:[{title:"A new name, a steady heart",reference:"Daniel 1:1\u20137",place:"Babylon",opening:"Daniel and his friends are taken far from home. A new language and royal training surround them.",objective:"Learn the surroundings without forgetting your identity.",discoveries:["The learning court","A friend\u2019s encouragement","Memories of home"],question:"How can you remain faithful in an unfamiliar culture?",choices:e("Learn thoughtfully while holding to my convictions.","Treat everyone from another culture with contempt.","Assume fitting in means I must abandon every conviction.","Faithfulness can combine conviction with humility and learning."),ending:"New surroundings do not erase an inner commitment."},{title:"A respectful request",reference:"Daniel 1:8\u201316",place:"The steward\u2019s table",opening:"Daniel has a concern about the royal food. The official fears the consequences of granting an exception.",objective:"Understand the official\u2019s concern and prepare a fair request.",discoveries:["The steward\u2019s responsibility","A simple meal","A measured proposal"],question:"How will you ask for a change?",choices:e("Explain respectfully and propose a reasonable trial.","Threaten the steward until he agrees.","Pretend the steward has no concerns worth hearing.","Daniel\u2019s request takes another person\u2019s responsibility seriously."),ending:"The steward agrees to the trial. Conviction has been expressed with respect."},{title:"No credit stolen",reference:"Daniel 2:17\u201323, 27\u201330",place:"The chamber of counsel",opening:"Facing the king\u2019s demand, Daniel asks his friends to pray. When the mystery is revealed, he refuses to claim superior wisdom for himself.",objective:"Seek shared counsel and prepare an honest answer.",discoveries:["The friends\u2019 prayer","A song of thanks","The king\u2019s summons"],question:"When an answer is given, who receives the credit?",choices:e("Acknowledge God and the support of those who prayed with me.","Claim I am better than every other person.","Use the answer to make my friends look foolish.","Integrity includes gratitude and honesty about the source of our help."),ending:"You enter the court with an answer and with gratitude."},{title:"An excellent spirit",reference:"Daniel 6:1\u20139",place:"The administrator\u2019s court",opening:"Other officials search for corruption in Daniel\u2019s work. Their plan turns toward his practice of prayer.",objective:"Complete the public duties entrusted to you.",discoveries:["An honest account","A neighbour\u2019s petition","The new decree"],question:"How will you exercise responsibility?",choices:e("Work honestly and treat people fairly, even when no one is watching.","Change the accounts to make myself richer.","Use my position to punish people I dislike.","Faithfulness is visible in ordinary integrity, not only dramatic moments."),ending:"They find no corruption to use against you. The decree creates a new danger."},{title:"Windows toward Jerusalem",reference:"Daniel 6:10\u201318",place:"The open window",opening:"Daniel continues his established pattern of prayer after hearing the decree. The king is distressed but orders him placed in the den.",objective:"Trace the places of prayer, accusation, and trust.",discoveries:["The open window","The familiar prayer place","The sealed entrance"],question:"Under pressure, what will guide you?",choices:e("Continue faithful prayer without using it to provoke or impress.","Turn prayer into a performance to humiliate others.","Blame the vulnerable for the decree.","The account describes a steady practice of trust, not a guarantee that faithful people avoid hardship."),ending:"The stone is set in place. Night falls over the lions\u2019 den."},{title:"Morning at the den",reference:"Daniel 6:19\u201323, 25\u201328",place:"The lions\u2019 den",opening:"At dawn the king hurries to the den and calls out. Daniel answers that God has sent his angel and shut the lions\u2019 mouths.",objective:"Walk through the quiet den toward the morning light.",discoveries:["The resting lions","The king\u2019s call","The open entrance"],question:"How will you answer after deliverance?",choices:e("Speak with gratitude and keep an undivided heart.","Use survival as permission to be cruel.","Claim that suffering proves someone lacks faith.","Daniel responds with testimony and gratitude. This story must not be used to blame people who suffer."),ending:"Morning light enters the den. Daniel is lifted out unharmed in the biblical account. Campaign complete."}]}],u="kairos-ltbs-progress-v1",c=()=>({completed:{},grace:0});function g(){try{let t=JSON.parse(localStorage.getItem(u)??"null");return!t||typeof t.completed!="object"||!t.completed||!Number.isFinite(t.grace)?c():{completed:t.completed,grace:Math.max(0,t.grace)}}catch{return c()}}function f(t,n,o,r){let i=d.find(l=>l.id===n)?.chapters[o];if(!i||!i.choices[r]||o>0&&!t.completed[`${n}:${o-1}`])return{save:t,earned:0};let s=`${n}:${o}`;if(t.completed[s])return{save:t,earned:0};let a=i.choices[r].grace;return{earned:a,save:{grace:t.grace+a,completed:{...t.completed,[s]:{choice:r,grace:a}}}}}export{d as a,u as b,c,g as d,f as e};
